<script setup>
import {ref,computed} from 'vue'
const props=defineProps({bilibili:String,youtube:String,title:{type:String,default:'教程视频'}});const provider=ref(props.bilibili?'bilibili':'youtube');const loaded=ref(false)
const src=computed(()=>provider.value==='bilibili'&&/^BV[a-zA-Z0-9]+$/.test(props.bilibili||'')?'https://player.bilibili.com/player.html?bvid='+props.bilibili+'&autoplay=0':provider.value==='youtube'&&/^[\w-]{11}$/.test(props.youtube||'')?'https://www.youtube-nocookie.com/embed/'+props.youtube:'')
</script><template><div class="video-embed"><div v-if="bilibili&&youtube" class="update-tabs"><button @click="provider='bilibili';loaded=false" :aria-pressed="provider==='bilibili'">B 站</button><button @click="provider='youtube';loaded=false" :aria-pressed="provider==='youtube'">YouTube</button></div><iframe v-if="loaded&&src" :src="src" :title="title" loading="lazy" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><button v-else-if="src" class="video-placeholder" @click="loaded=true"><span>▷</span>点击加载{{title}}<small>将连接 {{provider==='bilibili'?'B 站':'YouTube'}} 播放器</small></button><p v-else>视频地址无效，请检查视频编号。</p></div></template>
